pragma solidity ^0.8.20;

import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

/**
 * @title WETH interface
 * @author Term Structure Labs
 * @notice Interface for WETH contract
 */
interface IWETH is IERC20 {
