    THREE, // 3 months
    SIX, // 6 months
    NINE, // 9 months
    TWELVE // 12 months

}

uint256 constant NUMBER_OF_LOCK_DURATIONS = 4;

interface IRewardManager {
    event TroveManagerRegistered(ITroveManager);
    event TroveManagerRemoved(ITroveManager);
    event DebtTokenSet(address);
