    uint16 index;
}

interface IBorrowerOperationsFacet {
    event BorrowingFeePaid(address indexed borrower, IERC20 indexed collateralToken, uint256 amount);
    event TroveCreated(address indexed _borrower, uint256 arrayIndex);
    event TroveManagerRemoved(ITroveManager indexed troveManager);
    event MinNetDebtUpdated(uint256 _minNetDebt);
    event DelegateApprovalSet(address indexed caller, address indexed delegate, bool isApproved);

    function isApprovedDelegate(address _account, address _delegate) external view returns (bool);

    function setDelegateApproval(address _delegate, bool _isApproved) external;

    function addColl(
        ITroveManager _troveManager,
        address _account,
        uint256 _collateralAmount,
        address _upperHint,
        address _lowerHint
    )
        external;

    function adjustTrove(
        ITroveManager _troveManager,
        address _account,
        uint256 _maxFeePercentage,
        uint256 _collDeposit,
        uint256 _collWithdrawal,
        uint256 _debtChange,
        bool _isDebtIncrease,
        address _upperHint,
        address _lowerHint
    )
        external;

    function closeTrove(ITroveManager _troveManager, address _account) external;

    function fetchBalances() external returns (Balances memory balances);

    function getGlobalSystemBalances() external returns (uint256 totalPricedCollateral, uint256 totalDebt);

    function getTCR() external returns (uint256 globalTotalCollateralRatio);

    function openTrove(
        ITroveManager _troveManager,
        address _account,
        uint256 _maxFeePercentage,
        uint256 _collateralAmount,
        uint256 _debtAmount,
        address _upperHint,
        address _lowerHint
    )
        external;

    function removeTroveManager(ITroveManager _troveManager) external;

    function repayDebt(
        ITroveManager _troveManager,
        address _account,
        uint256 _debtAmount,
        address _upperHint,
        address _lowerHint
    )
        external;

    function setMinNetDebt(uint256 _minNetDebt) external;

    function withdrawColl(
        ITroveManager _troveManager,
        address _account,
        uint256 _collWithdrawal,
        address _upperHint,
        address _lowerHint
    )
        external;

    function withdrawDebt(
        ITroveManager _troveManager,
        address _account,
        uint256 _maxFeePercentage,
        uint256 _debtAmount,
        address _upperHint,
        address _lowerHint
    )
        external;

    function checkRecoveryMode(uint256 TCR) external pure returns (bool);

    function getCompositeDebt(uint256 _debt) external view returns (uint256);

    function minNetDebt() external view returns (uint256);

    function troveManagersData(ITroveManager _troveManager)
        external
        view
        returns (IERC20 collateralToken, uint16 index);

    function forceResetTM(ITroveManager[] calldata _troveManagers) external;
}

src/core/interfaces/IDebtToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { IERC3156FlashBorrower } from "@openzeppelin/contracts/interfaces/IERC3156FlashBorrower.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import { IERC20Metadata } from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Metadata.sol";
// import {IERC20Permit} from "@openzeppelin/contracts/token/ERC20/extensions/IERC20Permit.sol";

import { ITroveManager } from "./ITroveManager.sol";

interface IDebtToken is IERC20, IERC20Metadata {
    /**
     * @notice Burns a specific amount of tokens from the specified account.
     * @param _account The address from which the tokens will be burned.
     * @param _amount The amount of tokens to burn.
     */
    function burn(address _account, uint256 _amount) external;

    /**
     * @notice Burns a specific amount of tokens from the specified account with gas compensation.
     * @param _account The address from which the tokens will be burned.
     * @param _amount The amount of tokens to burn.
     */
    function burnWithGasCompensation(address _account, uint256 _amount) external;

    /**
     * @notice Enables a Trove Manager for the debt token.
     * @param _troveManager The Trove Manager to enable.
     */
    function enableTroveManager(ITroveManager _troveManager) external;

    /**
     * @notice Initiates a flash loan.
     * @param receiver The contract that will receive the flash loan.
     * @param token The address of the token to be loaned.
     * @param amount The amount of tokens to loan.
     * @param data Additional data to pass to the receiver.
     * @return A boolean indicating if the operation was successful.
     */
    function flashLoan(
        IERC3156FlashBorrower receiver,
        address token,
        uint256 amount,
        bytes calldata data
    )
        external
        returns (bool);

    /**
     * @notice Mints a specific amount of tokens to the specified account.
     * @param _account The address to which the tokens will be minted.
     * @param _amount The amount of tokens to mint.
     */
    function mint(address _account, uint256 _amount) external;

    /**
     * @notice Mints a specific amount of tokens to the specified account with gas compensation.
     * @param _account The address to which the tokens will be minted.
     * @param _amount The amount of tokens to mint.
     */
    function mintWithGasCompensation(address _account, uint256 _amount) external;

    /**
     * @notice Returns a specific amount of tokens from a pool to a receiver.
     * @param _poolAddress The address of the pool.
     * @param _receiver The address to receive the tokens.
     * @param _amount The amount of tokens to return.
     */
    function returnFromPool(address _poolAddress, address _receiver, uint256 _amount) external;

    /**
     * @notice Sends a specific amount of tokens to the Stability Pool.
     * @param _sender The address sending the tokens.
     * @param _amount The amount of tokens to send.
     */
    function sendToXApp(address _sender, uint256 _amount) external;

    /**
     * @notice Transfers a specific amount of tokens to a recipient.
     * @param recipient The address to receive the tokens.
     * @param amount The amount of tokens to transfer.
     * @return A boolean indicating if the operation was successful.
     */
    function transfer(address recipient, uint256 amount) external returns (bool);

    /**
     * @notice Transfers a specific amount of tokens from a sender to a recipient.
     * @param sender The address from which the tokens will be transferred.
     * @param recipient The address to receive the tokens.
     * @param amount The amount of tokens to transfer.
     * @return A boolean indicating if the operation was successful.
     */
    function transferFrom(address sender, address recipient, uint256 amount) external returns (bool);

    /**
     * @notice Returns the gas compensation amount for debt operations.
     * @return The gas compensation amount as a uint256.
     */
    function DEBT_GAS_COMPENSATION() external view returns (uint256);

    /**
     * @notice Returns the flash loan fee.
     * @return The flash loan fee as a uint256.
     */
    function FLASH_LOAN_FEE() external view returns (uint256);

    /**
     * @notice Returns the address of the SatoshiX application.
     * @return The address of the SatoshiX application.
     */
    function satoshiXApp() external view returns (address);

    /**
     * @notice Calculates the flash fee for a given token and amount.
     * @param token The address of the token.
     * @param amount The amount of tokens.
     * @return The flash fee as a uint256.
     */
    function flashFee(address token, uint256 amount) external view returns (uint256);

    /**
     * @notice Returns the maximum flash loan amount for a given token.
     * @param token The address of the token.
     * @return The maximum flash loan amount as a uint256.
     */
    function maxFlashLoan(address token) external view returns (uint256);

    /**
     * @notice Checks if a Trove Manager is enabled.
     * @param _troveManager The Trove Manager to check.
     * @return A boolean indicating if the Trove Manager is enabled.
     */
    function troveManager(ITroveManager _troveManager) external view returns (bool);

    /**
     * @notice Initializes the debt token with the specified parameters.
     * @param _name The name of the token.
     * @param _symbol The symbol of the token.
     * @param _gasPool The address of the gas pool.
     * @param _satoshiXApp The address of the SatoshiX application.
     * @param _owner The address of the owner.
     * @param _debtGasCompensation The gas compensation amount for debt operations.
     */
    function initialize(
        string memory _name,
        string memory _symbol,
        address _gasPool,
        address _satoshiXApp,
        address _owner,
        uint256 _debtGasCompensation
    )
        external;

    /**
     * @notice Checks if an address is authorized as a ward.
     * @param _address The address to check.
     * @return A boolean indicating if the address is a ward.
     */
    function wards(address _address) external view returns (bool);

    /**
     * @notice Grants authorization to an address.
     * @param _address The address to authorize.
     */
    function rely(address _address) external;

    /**
     * @notice Revokes authorization from an address.
     * @param _address The address to deauthorize.
     */
    function deny(address _address) external;
}

src/core/interfaces/INexusYieldManagerFa.content:
pragma solidity ^0.8.20;

import { IDebtToken } from "./IDebtToken.sol";
import { IPriceFeedAggregatorFacet } from "./IPriceFeedAggregatorFacet.sol";

struct AssetConfig {
    /// The incoming stableCoin fee. (Fee for swapIn).
    uint256 feeIn;
    /// The outgoing stableCoin fee. (Fee for swapOut).
    uint256 feeOut;
    /// The maximum amount of debtToken that can be minted through this contract.
    uint256 debtTokenMintCap;
    /// The maximum amount of debtToken that can be minted everyday.
    uint256 dailyDebtTokenMintCap;
    /// The total amount of debtToken minted through this asset.
    uint256 debtTokenMinted;
    /// The time used to wait after schedule the withdrawal.
    uint256 swapWaitingPeriod;
    /// The maximum price of the asset. If the price of the asset exceeds this value, the operation will revert.
    uint256 maxPrice;
    /// The minimum price of the asset. If the price of the asset is less than this value, the operation will revert.
    uint256 minPrice;
    /// A flag indicating whether the contract is using an oracle or not.
    bool isUsingOracle;
}

struct ChainConfig {
    address debtToken;
    address rollupMinter;
    address nexusYieldManager;
    address feeReceiver;
    uint64 mintGas;
    uint64 burnGas;
}

interface INexusYieldManagerFacet {
    // Helper enum for calculation of the fee.
    enum FeeDirection {
        IN,
        OUT
    }

    /// @notice Event emitted when contract is paused.
    event NYMPaused(address indexed admin);

    /// @notice Event emitted when the contract is resumed after pause.
    event NYMResumed(address indexed admin);

    /// @notice Event emitted when RewardManager state var is modified.
    event RewardManagerChanged(address indexed oldTreasury, address indexed newTreasury);

    /// @notice Event emitted when stable token is swapped for debtToken.
    event AssetForDebtTokenSwapped(
        address caller, address receiver, address asset, uint256 stableIn, uint256 tokenOut, uint256 fee
    );

    /// @notice Event emitted when stable token is swapped for debtToken.
    event DebtTokenForAssetSwapped(
        address caller, address receiver, address asset, uint256 debtTokenBurnt, uint256 stableOut, uint256 fee
    );

    /// @notice Event emitted when the status of a privileged user is changed.
    event PrivilegedSet(address privileged, bool isPrivileged);

    /// @notice Event emitted when a user schedules a swapOut.
    event WithdrawalScheduled(address asset, address user, uint256 amount, uint256 fee, uint32 time);

    /// @notice Event emitted when a user withdraws the scheduled swapOut.
    event Withdraw(address asset, address user, uint256 amount);

    /// @notice Event emitted when the token is transferred.
    event TokenTransferred(address indexed token, address indexed to, uint256 amount);

    /// @notice Event emitted when the asset configuration is set.
    event AssetConfigSetting(address asset, AssetConfig config);

    /// @notice Event emitted when an asset is sunset.
    event AssetSunset(address asset);

    /// @notice thrown when contract is in paused state
    error Paused();

    /// @notice thrown when attempted to pause an already paused contract
    error AlreadyPaused();

    /// @notice thrown when attempted to resume the contract if it is already resumed
    error NotPaused();

    /// @notice thrown when fee in or fee out is invalid
    error InvalidFee(uint256 feeIn, uint256 feeOut);

    /// @notice thrown when a zero address is passed as a function parameter
    error ZeroAddress();

    /// @notice thrown when a zero amount is passed as stable token amount parameter
    error ZeroAmount();

    /// @notice thrown when the user doesn't have enough debtToken balance to provide for the amount of stable tokens he wishes to get
    error NotEnoughDebtToken(uint256 debtBalance, uint256 stableTknAmount);

    /// @notice thrown when the amount of debtToken to be burnt exceeds the debtTokenMinted amount
    error DebtTokenMintedUnderflow(uint256 debtTokenMinted, uint256 stableTknAmount);

    /// @notice thrown when the debtToken is not enough to transfer
    error DebtTokenNotEnough(uint256 debtTokenAmount, uint256 transferAmount);

    /// @notice thrown when debtToken to be minted will go beyond the mintCap threshold
    error DebtTokenMintCapReached(uint256 debtTokenMinted, uint256 amountToMint, uint256 debtTokenMintCap);

    /// @notice thrown when debtToken to be minted will go beyond the daily mintCap threshold
    error DebtTokenDailyMintCapReached(uint256 dailyMinted, uint256 amountToMint, uint256 dailyDebtTokenMintCap);

    /// @notice thrown when fee calculation will result in rounding down to 0 due to stable token amount being a too small number
    error AmountTooSmall(uint256 feeAmount);

    /// @notice thrown when a user has already scheduled a swapOut
    error WithdrawalAlreadyScheduled(uint32 withdrawalTime);

    /// @notice thrown when a user tries to withdraw before the scheduled time or a user does not have a scheduled swapOut
    error WithdrawalNotAvailable(uint32 withdrawalTime);

    /// @notice thrown when the address is not privileged
    error NotPrivileged(address addr);

    /// @notice thrown when the asset is not supported
    error AssetNotSupported(address asset);

    /// @notice thrown when the price of the asset is greater than the max price or less than the min price
    error InvalidPrice(uint256 price);

    error InvalidSourceChainSender(address, address);

    error InvalidChainId();

    error AssetNotEnough(uint256 assetAmount, uint256 transferAmount);

    /**
     * @notice Sets the configuration for a specific asset.
     * @param asset The address of the asset.
     * @param config The configuration parameters for the asset.
     */
    function setAssetConfig(address asset, AssetConfig calldata config) external;

    /**
     * @notice Sunsets a specific asset, disabling its use.
     * @param asset The address of the asset to sunset.
     */
    function sunsetAsset(address asset) external;

    /**
     * @notice Returns the configuration for a specific asset.
     * @param asset The address of the asset.
     * @return The configuration parameters for the asset.
     */
    function getAssetConfig(address asset) external view returns (AssetConfig memory);

    /**
     * @notice Swaps a specified amount of an asset for debt tokens.
     * @param asset The address of the asset to swap.
     * @param receiver The address to receive the debt tokens.
     * @param assetAmount The amount of the asset to swap.
     * @return The amount of debt tokens received.
     */
    function swapIn(address asset, address receiver, uint256 assetAmount) external returns (uint256);

    /**
     * @notice Pauses the contract, disabling certain functions.
     */
    function pause() external;

    /**
     * @notice Resumes the contract, re-enabling certain functions.
     */
    function resume() external;

    /**
     * @notice Sets the privileged status of an account.
     * @param account The address of the account.
     * @param isPrivileged_ The privileged status to set.
     */
    function setPrivileged(address account, bool isPrivileged_) external;

    /**
     * @notice Transfers a specified amount of tokens to a privileged vault.
     * @param token The address of the token to transfer.
     * @param vault The address of the privileged vault.
     * @param amount The amount of tokens to transfer.
     */
    function transferTokenToPrivilegedVault(address token, address vault, uint256 amount) external;

    /**
     * @notice Previews the amount of debt tokens that would be received for a specified amount of stable tokens.
     * @param asset The address of the asset.
     * @param stableTknAmount The amount of stable tokens.
     * @return The amount of debt tokens and the fee.
     */
    function previewSwapOut(address asset, uint256 stableTknAmount) external returns (uint256, uint256);

    /**
     * @notice Previews the amount of stable tokens that would be received for a specified amount of debt tokens.
     * @param asset The address of the asset.
     * @param stableTknAmount The amount of stable tokens.
     * @return The amount of debt tokens and the fee.
     */
    function previewSwapIn(address asset, uint256 stableTknAmount) external returns (uint256, uint256);

    /**
     * @notice Swaps a specified amount of stable tokens for debt tokens for a privileged account.
     * @param asset The address of the asset.
     * @param receiver The address to receive the debt tokens.
     * @param stableTknAmount The amount of stable tokens to swap.
     * @return The amount of debt tokens received.
     */
    function swapOutPrivileged(address asset, address receiver, uint256 stableTknAmount) external returns (uint256);

    /**
     * @notice Swaps a specified amount of debt tokens for stable tokens for a privileged account.
     * @param asset The address of the asset.
     * @param receiver The address to receive the stable tokens.
     * @param stableTknAmount The amount of stable tokens to swap.
     * @return The amount of debt tokens received.
     */
    function swapInPrivileged(address asset, address receiver, uint256 stableTknAmount) external returns (uint256);

    /**
     * @notice Schedules a swap out of a specified amount of an asset.
     * @param asset The address of the asset.
     * @param amount The amount of the asset to swap out.
     * @return The scheduled time for the swap out.
     */
    function scheduleSwapOut(address asset, uint256 amount) external returns (uint256);

    /**
     * @notice Withdraws a previously scheduled swap out.
     * @param asset The address of the asset.
     */
    function withdraw(address asset) external;

    /**
     * @notice Converts a specified amount of debt tokens to the equivalent amount of an asset.
     * @param asset The address of the asset.
     * @param amount The amount of debt tokens.
     * @return The equivalent amount of the asset.
     */
    function convertDebtTokenToAssetAmount(address asset, uint256 amount) external view returns (uint256);

    /**
     * @notice Converts a specified amount of an asset to the equivalent amount of debt tokens.
     * @param asset The address of the asset.
     * @param amount The amount of the asset.
     * @return The equivalent amount of debt tokens.
     */
    function convertAssetToDebtTokenAmount(address asset, uint256 amount) external view returns (uint256);

    /**
     * @notice Returns the incoming fee for a specific asset.
     * @param asset The address of the asset.
     * @return The incoming fee.
     */
    function feeIn(address asset) external view returns (uint256);

    /**
     * @notice Returns the outgoing fee for a specific asset.
     * @param asset The address of the asset.
     * @return The outgoing fee.
     */
    function feeOut(address asset) external view returns (uint256);

    /**
     * @notice Returns the mint cap for debt tokens for a specific asset.
     * @param asset The address of the asset.
     * @return The mint cap.
     */
    function debtTokenMintCap(address asset) external view returns (uint256);

    /**
     * @notice Returns the daily mint cap for debt tokens for a specific asset.
     * @param asset The address of the asset.
     * @return The daily mint cap.
     */
    function dailyDebtTokenMintCap(address asset) external view returns (uint256);

    /**
     * @notice Returns the total amount of debt tokens minted for a specific asset.
     * @param asset The address of the asset.
     * @return The total amount of debt tokens minted.
     */
    function debtTokenMinted(address asset) external view returns (uint256);

    /**
     * @notice Returns whether an oracle is being used for a specific asset.
     * @param asset The address of the asset.
     * @return True if an oracle is being used, false otherwise.
     */
    function isUsingOracle(address asset) external view returns (bool);

    /**
     * @notice Returns the waiting period for swaps for a specific asset.
     * @param asset The address of the asset.
     * @return The waiting period.
     */
    function swapWaitingPeriod(address asset) external view returns (uint256);

    /**
     * @notice Returns the remaining daily mint cap for debt tokens for a specific asset.
     * @param asset The address of the asset.
     * @return The remaining daily mint cap.
     */
    function debtTokenDailyMintCapRemain(address asset) external view returns (uint256);

    /**
     * @notice Returns the pending withdrawal amount and time for a specific asset and account.
     * @param asset The address of the asset.
     * @param account The address of the account.
     * @return The pending withdrawal amount and time.
     */
    function pendingWithdrawal(address asset, address account) external view returns (uint256, uint32);

    /**
     * @notice Returns the pending withdrawals for multiple assets and an account.
     * @param assets The array of asset addresses.
     * @param account The address of the account.
     * @return The array of pending withdrawal amounts and times.
     */
    function pendingWithdrawals(
        address[] memory assets,
        address account
    )
        external
        view
        returns (uint256[] memory, uint32[] memory);

    /**
     * @notice Returns whether the contract is paused.
     * @return True if the contract is paused, false otherwise.
     */
    function isNymPaused() external view returns (bool);

    /**
     * @notice Returns the daily mint count for a specific asset.
     * @param asset The address of the asset.
     * @return The daily mint count.
     */
    function dailyMintCount(address asset) external view returns (uint256);

    /**
     * @notice Returns whether a specific asset is supported.
     * @param asset The address of the asset.
     * @return True if the asset is supported, false otherwise.
     */
    function isAssetSupported(address asset) external view returns (bool);
}

src/core/interfaces/IPriceFeedAggregator.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { IPriceFeed } from "../../priceFeed/interfaces/IPriceFeed.sol";
import { IERC20 } from "@openzeppelin/contracts/token/ERC20/IERC20.sol";

struct OracleRecord {
    IPriceFeed priceFeed;
    uint8 decimals;
}

interface IPriceFeedAggregatorFacet {
    /**
     * @notice Emitted when a new oracle is registered.
     * @param token The ERC20 token associated with the oracle.
     * @param priceFeed The price feed contract for the oracle.
     */
    event NewOracleRegistered(IERC20 indexed token, IPriceFeed indexed priceFeed);

    // Custom Errors --------------------------------------------------------------------------------------------------

    /**
     * @notice Error indicating an invalid price feed address.
     */
    error InvalidPriceFeedAddress();

    /**
     * @notice Error indicating an invalid response from the price feed.
     * @param priceFeed The price feed contract that returned an invalid response.
     */
    error InvalidFeedResponse(IPriceFeed priceFeed);

    /**
     * @notice Fetches the price of a given token.
     * @param _token The ERC20 token for which the price is to be fetched.
     * @return The price of the token in the smallest unit.
     */
    function fetchPrice(IERC20 _token) external returns (uint256);

    /**
     * @notice Fetches the price of a given token without safety checks.
     * @param _token The ERC20 token for which the price is to be fetched.
     * @return The price of the token and the timestamp of the price.
     */
    function fetchPriceUnsafe(IERC20 _token) external returns (uint256, uint256);

    /**
     * @notice Sets the price feed for a given token.
     * @param _token The ERC20 token for which the price feed is to be set.
     * @param _priceFeed The price feed contract to be associated with the token.
     */
    function setPriceFeed(IERC20 _token, IPriceFeed _priceFeed) external;

    /**
     * @notice Returns the oracle record for a given token.
     * @param _token The ERC20 token for which the oracle record is to be retrieved.
     * @return priceFeed The price feed contract associated with the token.
     * @return decimals The number of decimals used by the price feed.
     */
    function oracleRecords(IERC20 _token) external view returns (IPriceFeed priceFeed, uint8 decimals);
}

src/core/interfaces/ISortedTroves.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import { ITroveManager } from "./ITroveManager.sol";

/// @title ISortedTroves
/// @notice Interface for managing a sorted list of troves based on their NICR (Nominal Individual Collateral Ratio).
interface ISortedTroves {
    /// @notice Emitted when a node is added to the list.
    /// @param _id The address of the node added.
    /// @param _NICR The NICR of the node added.
    event NodeAdded(address _id, uint256 _NICR);

    /// @notice Emitted when a node is removed from the list.
    /// @param _id The address of the node removed.
    event NodeRemoved(address _id);

    /// @notice Emitted when the Trove Manager is set.
    /// @param _troveManager The address of the Trove Manager contract.
    event SetTroveManager(address _troveManager);

    /// @notice Initializes the contract with the given owner.
    /// @param owner The address of the owner.
    function initialize(address owner) external;

    /// @notice Inserts a node into the list.
    /// @param _id The address of the node to insert.
    /// @param _NICR The NICR of the node to insert.
    /// @param _prevId The address of the previous node in the list.
    /// @param _nextId The address of the next node in the list.
    function insert(address _id, uint256 _NICR, address _prevId, address _nextId) external;

    /// @notice Re-inserts a node into the list with a new NICR.
    /// @param _id The address of the node to re-insert.
    /// @param _newNICR The new NICR of the node.
    /// @param _prevId The address of the previous node in the list.
    /// @param _nextId The address of the next node in the list.
    function reInsert(address _id, uint256 _newNICR, address _prevId, address _nextId) external;

    /// @notice Removes a node from the list.
    /// @param _id The address of the node to remove.
    function remove(address _id) external;

    /// @notice Sets the configuration for the Trove Manager.
    /// @param _troveManager The address of the Trove Manager contract.
    function setConfig(ITroveManager _troveManager) external;

    /// @notice Checks if a node exists in the list.
    /// @param _id The address of the node to check.
    /// @return True if the node exists, false otherwise.
    function contains(address _id) external view returns (bool);

    /// @notice Returns the data of the list.
    /// @return head The address of the head node.
    /// @return tail The address of the tail node.
    /// @return size The current size of the list.
    function data() external view returns (address head, address tail, uint256 size);

    /// @notice Finds the insert position for a node with a given NICR.
    /// @param _NICR The NICR of the node to insert.
    /// @param _prevId The address of the previous node in the list.
    /// @param _nextId The address of the next node in the list.
    /// @return The addresses of the previous and next nodes for the insert position.
    function findInsertPosition(
        uint256 _NICR,
        address _prevId,
        address _nextId
    )
        external
        view
        returns (address, address);

    /// @notice Gets the first node in the list.
    /// @return The address of the first node.
    function getFirst() external view returns (address);

    /// @notice Gets the last node in the list.
    /// @return The address of the last node.
    function getLast() external view returns (address);

    /// @notice Gets the next node in the list for a given node.
    /// @param _id The address of the current node.
    /// @return The address of the next node.
    function getNext(address _id) external view returns (address);

    /// @notice Gets the previous node in the list for a given node.
    /// @param _id The address of the current node.
    /// @return The address of the previous node.
    function getPrev(address _id) external view returns (address);

    /// @notice Gets the size of the list.
    /// @return The current size of the list.
    function getSize() external view returns (uint256);

    /// @notice Checks if the list is empty.
    /// @return True if the list is empty, false otherwise.
    function isEmpty() external view returns (bool);

    /// @notice Gets the Trove Manager contract.
    /// @return The address of the Trove Manager contract.
    function troveManager() external view returns (ITroveManager);

    /// @notice Validates the insert position for a node with a given NICR.
    /// @param _NICR The NICR of the node to insert.
    /// @param _prevId The address of the previous node in the list.
    /// @param _nextId The address of the next node in the list.
    /// @return True if the insert position is valid, false otherwise.
    function validInsertPosition(uint256 _NICR, address _prevId, address _nextId) external view returns (bool);
}

// Information for a node in the list
struct Node {
    bool exists;
    ///< Indicates if the node exists in the list.
    address nextId;
    ///< Id of next node (smaller NICR) in the list.
    address prevId;
}
///< Id of previous node (larger NICR) in the list.

// Information for the list
struct Data {
    address head;
    ///< Head of the list. Also the node in the list with the largest NICR.
    address tail;
    ///< Tail of the list. Also the node in the list with the smallest NICR.
    uint256 size;
    ///< Current size of the list.
    mapping(address => Node) nodes;
}
///< Track the corresponding ids for each node in the list.

